  "scheduler.templateCategoryDevelopment": "Development automation",
  "scheduler.templateCategoryRadar": "Information radar",
  "scheduler.templateCategoryOffice": "Docs & office work",
  "scheduler.templateTopicLabel": "Topic to follow",
  "scheduler.templateTopicPlaceholder": "e.g. AI agents, EV market, frontend frameworks",
  "scheduler.templateCompetitorsLabel": "Competitors",
  "scheduler.templateCompetitorsPlaceholder": "e.g. Notion, Linear, Figma",
  "scheduler.templateNightlyTestName": "Nightly test self-healing",
  "scheduler.templateNightlyTestDescription": "Run tests every night and attempt minimal fixes for failures in an isolated worktree",
  "scheduler.templateNightlyTestPrompt": "Run the project's test suite. If there are failures, attempt a minimal fix in an isolated worktree.\nConstraints:\n- Determine the standard test command from the repository documentation or package scripts before running the full suite\n- Only fix issues backed by clear failing evidence; prefer the smallest possible change and avoid unrelated refactoring\n- Re-run the affected tests after fixing to confirm they pass, and review the full diff\n- Deliver fixes through the repository's workflow, such as creating a branch and opening a pull request; never commit directly to the main branch\n- For failures that cannot be fixed safely, report the cause, suspicious files, and suggested next steps",
  "scheduler.templatePullRequestName": "PR gatekeeper",
  "scheduler.templatePullRequestDescription": "Pre-review new changes on open pull requests each weekday and report risks by severity",
  "scheduler.templatePullRequestPrompt": "Review the repository's open pull requests and pre-screen their new changes.\nConstraints:\n- Go through open pull requests with new commits in the past 24 hours; on Monday, look back over the whole weekend. Cite pull-request numbers, file paths, and concrete diffs\n- Focus on correctness, security, data-loss, and compatibility issues, graded by severity\n- Only report issues backed by evidence and describe the failure scenario; do not nitpick on style preferences\n- Unless explicitly authorized, only output review conclusions; do not comment on pull requests or change code",
  "scheduler.templateTopicRadarName": "Domain radar",
  "scheduler.templateTopicRadarDescription": "Periodically collect the latest updates in a topic you follow and deliver an opinionated digest",
  "scheduler.templateTopicRadarPrompt": "Collect the latest developments about \"{{topic}}\" from the past 24 hours; on Monday, look back over the whole weekend. Produce an opinionated digest.\nConstraints:\n- Use web search, cross-check multiple sources before trusting a claim, and cite the source link for every item\n- Prefer substantive developments such as releases, research, policy, and notable discussions; filter out marketing material and reposts\n- For each item, add a one-line judgement on why it matters instead of listing links\n- When information is scarce or sources are questionable, say so honestly; never fabricate",
  "scheduler.templateCompetitorName": "Competitor watch",
  "scheduler.templateCompetitorDescription": "Weekly roundup of competitors' product and market moves, with impact analysis",
  "scheduler.templateCompetitorPrompt": "Track the past week's activity of these competitors: {{competitors}}.\nConstraints:\n- Use web search to cover product updates, releases, pricing changes, market moves, and user sentiment, citing sources\n- Distinguish official information from third-party accounts; clearly mark unverified rumors\n- For each significant update, analyze what it means for us and suggest a response\n- If nothing substantive happened, say so honestly instead of padding the report",
  "scheduler.templateWeeklyReportName": "Weekly report drafter",
  "scheduler.templateWeeklyReportDescription": "Compile this week's work from documents in the working directory into a report draft",
  "scheduler.templateWeeklyReportPrompt": "Based on this week's changes to documents, notes, and deliverables in the working directory, compile a weekly report draft.\nConstraints:\n- Only use content with actual modification traces in the working directory as evidence, citing the files\n- Organize as \"Done this week / In progress / Next week / Needs coordination\", concise enough to submit directly\n- Separate substantive progress from routine chores and highlight valuable output\n- Leave placeholders with notes where the material is insufficient so the user can fill them in",
  "scheduler.templateDocumentationName": "Knowledge base freshness check",
  "scheduler.templateDocumentationDescription": "Monthly health check of working-directory documents for outdated or conflicting content",
  "scheduler.templateDocumentationPrompt": "Health-check the documents in the working directory and find content that needs updating.\nConstraints:\n- Look for outdated information such as stale dates, dead links, and deprecated processes or tools, as well as contradictions and duplication\n- Cite the file path and location for every issue and explain the reasoning\n- Categorize the findings as update, merge, or delete suggestions and produce a revision checklist\n- Only output the report; do not modify the documents",
