  "scheduler.templateBlank": "空白创建", "scheduler.templateUseTemplate": "使用模板", "scheduler.templateHeading": "从模板开始", "scheduler.templateParameters": "自定义模板", "scheduler.templateWorktree": "隔离工作树", "scheduler.templatePullRequest": "Pull Request", "scheduler.templateWeb": "网页搜索", "scheduler.templateCustomizable": "可自定义",
  "scheduler.templateCategoryDevelopment": "开发自动化", "scheduler.templateCategoryRadar": "信息雷达", "scheduler.templateCategoryOffice": "文档与办公", "scheduler.templateTopicLabel": "关注主题", "scheduler.templateTopicPlaceholder": "例如：AI Agent、新能源、前端框架", "scheduler.templateCompetitorsLabel": "竞品名单", "scheduler.templateCompetitorsPlaceholder": "例如：Notion、Linear、Figma",
  "scheduler.templateNightlyTestName": "夜间自愈测试", "scheduler.templateNightlyTestDescription": "每晚运行测试，在隔离工作树中尝试最小修复失败项", "scheduler.templateNightlyTestPrompt": "运行项目的测试套件；如果存在失败项，在隔离工作树中尝试给出最小修复。\n约束：\n- 先按仓库文档或 package 脚本确定标准测试命令，再完整运行\n- 只修复有明确失败证据的问题，采用影响面最小的改法，避免无关重构\n- 修复后重跑相关测试确认通过，并复核完整差异\n- 按仓库工作流交付修复，例如创建分支并开启 Pull Request；不要直接改动主分支\n- 无法安全修复的失败项，输出失败原因、疑点文件和建议的排查步骤",
  "scheduler.templatePullRequestName": "PR 守门人", "scheduler.templatePullRequestDescription": "工作日预审开放 Pull Request 的新增改动，按严重程度报告风险", "scheduler.templatePullRequestPrompt": "检查仓库当前开放的 Pull Request，对新增改动做一轮预审。\n约束：\n- 逐个查看过去 24 小时内有新提交的开放 Pull Request；周一回看整个周末。引用编号、文件路径和具体差异\n- 重点查找正确性、安全、数据丢失和兼容性问题，按严重程度分级\n- 只报告有证据支撑的问题，说明失败场景，不要凭风格偏好挑刺\n- 除非用户明确授权，只输出审查结论，不要直接留言或改动代码",
  "scheduler.templateTopicRadarName": "领域雷达", "scheduler.templateTopicRadarDescription": "定期搜集你关注领域的最新动态，输出有观点的摘要", "scheduler.templateTopicRadarPrompt": "围绕主题「{{topic}}」搜集过去 24 小时的最新动态；周一回看整个周末。输出一份有观点的摘要。\n约束：\n- 使用网页搜索获取信息，交叉核对多个来源后再采信，标注每条信息的来源链接\n- 优先收录发布、研究、政策和重要讨论等实质进展，过滤营销内容和重复转载\n- 对每条动态给出一句为什么值得关注的判断，而不是罗列链接\n- 信息不足或来源存疑时如实说明，不要臆造",
  "scheduler.templateCompetitorName": "竞品动态追踪", "scheduler.templateCompetitorDescription": "每周汇总竞品的产品与市场动态，分析对我们的影响", "scheduler.templateCompetitorPrompt": "追踪以下竞品最近一周的动态：{{competitors}}。\n约束：\n- 使用网页搜索覆盖产品更新、版本发布、定价变化、市场动作和用户口碑，标注来源\n- 区分官方信息和第三方转述，未经证实的传闻要明确标注\n- 对每条重要动态给出对我们的影响分析和建议\n- 没有实质动态时如实说明，不要凑数",
  "scheduler.templateWeeklyReportName": "周报草稿助手", "scheduler.templateWeeklyReportDescription": "从工作目录的文档和产出物整理本周工作，生成周报草稿", "scheduler.templateWeeklyReportPrompt": "根据工作目录中本周的文档、笔记和产出物变化，整理一份周报草稿。\n约束：\n- 只使用工作目录内有实际修改痕迹的内容作为证据，注明对应文件\n- 按“本周完成 / 进行中 / 下周计划 / 需要协调”组织，语言简洁可直接提交\n- 区分实质进展和例行事务，突出有价值的产出\n- 材料不足以判断的部分留出占位并说明，方便用户补充",
  "scheduler.templateDocumentationName": "知识库保鲜", "scheduler.templateDocumentationDescription": "每月体检工作目录文档，找出过期与矛盾内容", "scheduler.templateDocumentationPrompt": "体检工作目录中的文档，找出需要更新的内容。\n约束：\n- 检查旧日期、失效链接、已废弃流程或工具等过期信息，以及前后矛盾和重复内容\n- 每个问题都注明文件路径和具体位置，说明判断依据\n- 按建议更新、建议合并和建议删除分类，给出修订建议清单\n- 只输出体检报告，不要直接修改文档",
