export function translate(locale: Locale, key: MessageKey, values?: Readonly<Record<string, string | number>>): string {
  let value = presentJokoServiceTerminology(locale === "zh-CN" ? zh[key] : en[key]);
  if (locale === "en-XA") value = pseudoLocalize(value);
  for (const [name, replacement] of Object.entries(values ?? {})) value = value.replaceAll(`{${name}}`, String(replacement));
  return value;
}

function pseudoLocalize(value: string): string {
  const accents: Readonly<Record<string, string>> = { a: "à", e: "ë", i: "ï", o: "õ", u: "ü", A: "Â", E: "Ë", I: "Ï", O: "Ö", U: "Û" };
  const localized = value.split(/(\{[^{}]+\})/u).map((segment) => /^\{[^{}]+\}$/u.test(segment) ? segment : [...segment].map((character) => accents[character] ?? character).join("")).join("");
  return `［${localized}··］`;
}
